<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {http,dataOf} from '../api/http';import {stepUpHeader,withStepUp} from '../api/stepUp';import {useAuthStore} from '../stores/auth';const auth=useAuthStore(),data=ref<any>({}),report=ref<any>({}),loading=ref(true),exporting=ref(false)
onMounted(async()=>{try{const [overview,decision]=await Promise.all([http.get('/dashboard'),http.get('/dashboard/report')]);data.value=dataOf(overview);report.value=dataOf(decision)}finally{loading.value=false}})
async function exportReport(){exporting.value=true;try{const endpoint='/dashboard/report/export';const blob=await withStepUp({purpose:'EXPORT',method:'GET',target:endpoint,label:'导出当前权限范围的决策分析报表'},token=>http.get(endpoint,{responseType:'blob',headers:stepUpHeader(token)})) as unknown as Blob;const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download='decision-report.csv';anchor.click();URL.revokeObjectURL(url)}finally{exporting.value=false}}
function rate(value:any){return `${Number(value||0).toFixed(1)}%`}
function label(value:any){return ({PUBLISHED:'已发布',PENDING_REVIEW:'待审核',APPROVED:'已批准',REJECTED:'已驳回',DRAFT:'草稿',ONLINE:'在线',OFFLINE:'离线'} as any)[String(value)]||value}
const cards=computed(()=>[
 ['templateCount','完整模板','可复用的数据治理标准','◇'],['fragmentCount','模板片段','可组合的字段与章节','◫'],
 ['datasetCount','数据集','统一纳管的数据资产','▦'],['recordCount','数据量','当前账号可见记录','≋'],
 ['publishedRecordCount','已发布数据','审核发布的可信记录','✓'],['publishingRecordCount','发布中数据','待审核或审核通过','↻']
].filter(card=>data.value[card[0]]!==null&&data.value[card[0]]!==undefined))
</script>
<template><div class="page" v-loading="loading"><div class="hero"><div><p class="kicker">DATA OPERATIONS CENTER</p><h1>研发与生产数据治理工作台</h1><p>从研发试验到生产质量，关键数据在统一治理框架内持续汇聚。</p></div><div class="hero-status"><span><i></i>指标状态</span><b>工作台数据已刷新</b><small>服务健康请以顶部实时状态为准</small></div></div>
 <div class="metric-grid"><div v-for="c in cards" :key="c[0]" class="metric surface"><div class="metric-icon">{{c[3]}}</div><div><span>{{c[1]}}</span><strong>{{Number(data[c[0]]||0).toLocaleString()}}</strong><small>{{c[2]}}</small></div></div></div>
 <section class="surface workflow-guide"><div><b>1</b><span>模板创建</span><small>建立字段、章节与约束</small><router-link v-if="auth.can('template:create')" to="/templates">进入模板中心</router-link></div><i>→</i><div><b>2</b><span>数据上传</span><small>在线录入或批量导入</small><router-link v-if="auth.can('dataset:create')||auth.can('dataset:import')" to="/datasets">进入数据资产</router-link></div><i>→</i><div><b>3</b><span>数据发布</span><small>提交、独立审核并签名发布</small><router-link v-if="auth.can('dataset:update')||auth.can('dataset:audit')||auth.can('dataset:publish')" to="/datasets">处理发布流程</router-link></div></section>
 <section class="surface decision"><div class="decision-head"><div><h3>决策分析报表</h3><p>按当前账号权限与数据域实时汇总 · {{report.generatedTime?new Date(report.generatedTime).toLocaleString():'正在生成'}}</p></div><el-button v-if="auth.can('dataset:export')" :loading="exporting" @click="exportReport">导出 CSV</el-button></div>
  <div class="kpis"><div><span>数据发布率</span><strong>{{rate(report.kpis?.publicationRate)}}</strong></div><div><span>设备在线率</span><strong>{{rate(report.kpis?.onlineRate)}}</strong></div><div><span>待审核记录</span><strong>{{Number(report.kpis?.pendingReview||0).toLocaleString()}}</strong></div><div><span>授权数据域</span><strong>{{Number(report.scopeCount||0).toLocaleString()}}</strong></div></div>
  <div class="report-grid"><div class="report-block"><h4>记录生命周期</h4><p v-for="item in report.recordLifecycle||[]" :key="item.name"><span>{{label(item.name)}}</span><b>{{item.value}}</b></p><small v-if="!report.recordLifecycle?.length">暂无可见记录</small></div><div class="report-block"><h4>数据集分类</h4><p v-for="item in report.datasetByCategory||[]" :key="item.name"><span>{{item.name}}</span><b>{{item.value}}</b></p><small v-if="!report.datasetByCategory?.length">暂无分类数据</small></div><div class="report-block"><h4>近 30 天发布趋势</h4><p v-for="item in report.publicationTrend||[]" :key="item.name"><span>{{item.name}}</span><b>{{item.value}}</b></p><small v-if="!report.publicationTrend?.length">近期暂无发布记录</small></div></div>
 </section>
 <div class="dashboard-grid"><section v-if="auth.can('device:read')" class="surface panel trend"><div class="panel-head"><div><h3>设备数据采集趋势</h3><p>近 7 天接收的有效测点</p></div><span class="pill">实时数据</span></div><div class="bars"><div v-for="(item,i) in data.deviceTrend||[]" :key="item.day" class="bar-wrap"><div class="bar" :style="{height:Math.max(8,Number(item.value)*12)+'px',opacity:.55+Number(i)*.07}"><b>{{item.value}}</b></div><span>{{item.day}}</span></div><div v-if="!data.deviceTrend?.length" class="empty-note">尚无近期采集数据</div></div></section>
  <section class="surface panel health-card"><div class="panel-head"><div><h3>数据底座</h3><p>跨存储职责概览，实时健康以顶部状态为准</p></div></div><div class="store"><i class="pg">PG</i><div><b>PostgreSQL</b><span>主数据 · 权限 · 审计</span></div><em>已接入</em></div><div class="store"><i class="mg">M</i><div><b>MongoDB</b><span>动态数据集记录</span></div><em>已接入</em></div><div class="store"><i class="rd">R</i><div><b>Redis</b><span>会话 · 验证码 · 幂等</span></div><em>已接入</em></div></section>
	  <section class="surface panel quick"><div class="panel-head"><div><h3>快捷入口</h3><p>常用业务操作</p></div></div><div class="quick-grid"><router-link v-if="auth.can('dataset:read')" to="/datasets"><b>＋</b><span>数据资产</span></router-link><router-link v-if="auth.can('template:read')" to="/templates"><b>◇</b><span>采集模板</span></router-link><router-link v-if="auth.can('trace:read')" to="/trace"><b>⌘</b><span>查询追溯链</span></router-link><router-link v-if="auth.can('device:read')" to="/devices"><b>⌁</b><span>设备监控</span></router-link></div></section>
	  <section class="surface panel governance"><div class="panel-head"><div><h3>治理快照</h3><p>当前授权范围内的实时汇总</p></div></div><div class="ring-row"><div class="ring"><strong>LIVE</strong><span>实时指标</span></div><div class="gov-list"><p v-if="data.templates!=null"><span>模板资产</span><b>{{data.templates}}</b></p><p v-if="data.devices!=null"><span>设备总数</span><b>{{data.devices}}</b></p><p v-if="data.auditEventsToday!=null"><span>今日审计事件</span><b>{{data.auditEventsToday}}</b></p></div></div></section>
 </div></div></template>
